import{f as t,o as i,c as a,ar as s}from"./chunks/framework.HWAOx3Ef.js";const h=JSON.parse('{"title":"Duplizieren von Stimmzetteln","description":"","frontmatter":{},"headers":[],"relativePath":"technik/guides/duplicate-stimmzettel.md","filePath":"technik/guides/duplicate-stimmzettel.md"}'),n={name:"technik/guides/duplicate-stimmzettel.md"};function r(l,e,d,o,c,u){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="duplizieren-von-stimmzetteln" tabindex="-1">Duplizieren von Stimmzetteln <a class="header-anchor" href="#duplizieren-von-stimmzetteln" aria-label="Permalink to &quot;Duplizieren von Stimmzetteln&quot;">​</a></h1><h2 id="ausgangslage" tabindex="-1">Ausgangslage <a class="header-anchor" href="#ausgangslage" aria-label="Permalink to &quot;Ausgangslage&quot;">​</a></h2><p>Zum Testen, insbesondere der Performance, ist es wichtig, eine größere Menge von Stimmzetteln zu haben. Um diese nicht alle manuell erfassen zu müssen, wurde ein DB-Skript (Stored Procedure) erstellt, mit dem man einen Stimmzettel n-fach duplizieren kann.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Das Skript <code>createStoredProcedureToGenerateUUIDv4.sql</code> sowie <code>createStoreProcedureForStimmzettelDuplication.sql</code> (aus <code>wls-ergebnismeldung-service\\src\\test\\resources\\db\\oracle</code>) müssen in der Umgebung und im Schema des Ergebnismeldungsservices ausgeführt werden, in dem die Funktionalität zur Verfügung stehen soll.</p><h2 id="ausfuhrung" tabindex="-1">Ausführung <a class="header-anchor" href="#ausfuhrung" aria-label="Permalink to &quot;Ausführung&quot;">​</a></h2><p>Um einen Stimmzettel n-fach zu duplizieren, muss das folgende Statement ausgeführt werden:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CALL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> duplicate_stimmzettel(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wahlID&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wahlbezirkID&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;teamID&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, stimmzettelkennung, n);</span></span></code></pre></div><p>Die Parameter <code>wahlID</code>, <code>wahlbezirkID</code>, <code>teamID</code> und <code>stimmzettelkennung</code> beschreiben den Stimmzettel, der dupliziert werden soll. Der Parameter <code>n</code> gibt an, wie viele Duplikate erzeugt werden sollen. Dabei werden die Wahlvorschläge, Kandidaten und Beschlüsse entsprechend dupliziert.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Die duplizierten Stimmzettel werden am Ende, also nach dem höchsten Wert der <code>stimmzettelkennung</code> des Teams, eingefügt.</p></div><div class="note custom-block github-alert"><p class="custom-block-title">BrowserCache (IndexedDB leeren)</p><p>Ist der Service-Worker aktiv wird es notwendig sein, die IndexedDB zu leeren damit die duplizierten Stimmzettel sichtbar werden. Eine Leerung erfolgt auch im Rahmen eines Benutzerwechsels.</p></div><h2 id="disclaimer-zu-erzeugten-ids" tabindex="-1">Disclaimer zu erzeugten IDs <a class="header-anchor" href="#disclaimer-zu-erzeugten-ids" aria-label="Permalink to &quot;Disclaimer zu erzeugten IDs&quot;">​</a></h2><p>Die UUIDs, die mit dem Skript erstellt werden, verwenden einen anderen Algorithmus als der Service. Es ist daher möglich, dass im Laufe der Zeit Konflikte auftreten können.</p>',13)])])}const p=t(n,[["render",r]]);export{h as __pageData,p as default};
